50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
69	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
70	     */
71	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
72	
73	    /**
74	     * Common street-type abbreviations expanded during address normalization. Keys and values are
75	     * upper-cased, matching the state of the address after whitespace and case normalization.
76	     */
77	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
78	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper) {
92	        this.clinicService = clinicService;
93	        this.ownerMapper = ownerMapper;
94	        this.petMapper = petMapper;
95	        this.visitMapper = visitMapper;
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
101	        Collection<Owner> owners;
102	        if (lastName != null) {
103	            owners = this.clinicService.findOwnerByLastName(lastName);
104	        } else {
105	            owners = this.clinicService.findAllOwners();
106	        }
107	        if (owners.isEmpty()) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
116	        Owner owner = this.clinicService.findOwnerById(ownerId);
117	        if (owner == null) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
126	        validateRequiredOwnerFields(ownerFieldsDto);
127	        HttpHeaders headers = new HttpHeaders();
128	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
129	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
130	        owner.setTelephone(normalizedTelephone);
131	        owner.setEmail(normalizeEmail(owner.getEmail()));
132	        owner.setAddress(normalizeAddress(owner.getAddress()));
133	        if (owner.getRegistrationDate() == null) {
134	            owner.setRegistrationDate(LocalDate.now());
135	        }
136	        rejectDuplicateTelephone(normalizedTelephone);
137	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
138	            assignHousehold(owner);
139	        } else {
140	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
141	        }
142	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
143	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
144	        this.clinicService.saveOwner(owner);
145	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
146	        headers.setLocation(UriComponentsBuilder.newInstance()
147	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
148	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
154	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
155	        if (currentOwner == null) {
156	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
157	        }
158	        currentOwner.setAddress(ownerFieldsDto.getAddress());
159	        currentOwner.setCity(ownerFieldsDto.getCity());
160	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
161	        currentOwner.setLastName(ownerFieldsDto.getLastName());
162	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
163	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
164	        this.clinicService.saveOwner(currentOwner);
165	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Transactional
170	    @Override
171	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
172	        Owner owner = this.clinicService.findOwnerById(ownerId);
173	        if (owner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        this.clinicService.deleteOwner(owner);
177	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
183	        Owner owner = this.clinicService.findOwnerById(ownerId);
184	        if (owner == null) {
185	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
186	        }
187	        HttpHeaders headers = new HttpHeaders();
188	        Pet pet = petMapper.toPet(petFieldsDto);
189	        owner.setId(ownerId);
190	        pet.setOwner(owner);
191	        pet.getType().setName(null);
192	        this.clinicService.savePet(pet);
193	        PetDto petDto = petMapper.toPetDto(pet);
194	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
195	            .buildAndExpand(pet.getId()).toUri());
196	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
202	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
203	        if (currentOwner != null) {
204	            Pet currentPet = this.clinicService.findPetById(petId);
205	            if (currentPet != null) {
206	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
207	                currentPet.setName(petFieldsDto.getName());
208	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
209	                this.clinicService.savePet(currentPet);
210	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
211	            }
212	        }
213	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
214	    }
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
219	        HttpHeaders headers = new HttpHeaders();
220	        Visit visit = visitMapper.toVisit(visitFieldsDto);
221	        Pet pet = new Pet();
222	        pet.setId(petId);
223	        visit.setPet(pet);
224	        this.clinicService.saveVisit(visit);
225	        VisitDto visitDto = visitMapper.toVisitDto(visit);
226	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
227	            .buildAndExpand(visit.getId()).toUri());
228	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
229	    }
230	
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Override
234	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
235	        Owner owner = this.clinicService.findOwnerById(ownerId);
236	        if (owner != null) {
237	            Pet pet = owner.getPet(petId);
238	            if (pet != null) {
239	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
240	            }
241	        }
242	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
243	    }
244	
245	    /**
246	     * Builds the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
247	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3}
248	     * is the upper-cased first three letters of the owner's last name, and {@code NNNN} is a per-city
249	     * 4-digit zero-padded sequence equal to one more than the number of owners already in that city.
250	     * For example an owner named "Smithers" in "Springfield" created when 10 owners already live in
251	     * Springfield gets {@code 'SPR-SMI-0011'}.
252	     *
253	     * @param city the owner's city
254	     * @param lastName the owner's last name
255	     * @return the assigned customer code
256	     */
257	    /**
258	     * Counts how many existing owners share the given first and last name, compared
259	     * case-insensitively, at the moment before the new owner is persisted. The result is
260	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
261	     * stood when the owner was created rather than being recomputed on later reads.
262	     *
263	     * @param firstName the first name of the owner being created
264	     * @param lastName the last name of the owner being created
265	     * @return the number of pre-existing owners with the same first and last name
266	     */
267	    private int countNamesakes(String firstName, String lastName) {
268	        String first = firstName == null ? "" : firstName;
269	        String last = lastName == null ? "" : lastName;
270	        return (int) this.clinicService.findAllOwners().stream()
271	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
272	                && last.equalsIgnoreCase(existing.getLastName()))
273	            .count();
274	    }
275	
276	    private String nextCustomerCode(String city, String lastName) {
277	        String cityLetters = city == null ? "" : city;
278	        String city3 = cityLetters.substring(0, Math.min(3, cityLetters.length())).toUpperCase(Locale.ROOT);
279	        String letters = lastName == null ? "" : lastName;
280	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
281	        String normalizedCity = normalizeForComparison(city);
282	        int sequence = (int) this.clinicService.findAllOwners().stream()
283	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
284	            .count() + 1;
285	        return String.format("%s-%s-%04d", city3, last3, sequence);
286	    }
287	
288	    /**
289	     * Rejects an owner payload that is missing or blank in any of the required fields
290	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
291	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
292	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
293	     * guard enforces the rule uniformly for every required field.
294	     *
295	     * @param ownerFieldsDto the submitted owner payload
296	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
297	     */
298	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
299	        List<String> invalidFields = new ArrayList<>();
300	        if (isBlank(ownerFieldsDto.getFirstName())) {
301	            invalidFields.add("firstName");
302	        }
303	        if (isBlank(ownerFieldsDto.getLastName())) {
304	            invalidFields.add("lastName");
305	        }
306	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
307	            invalidFields.add("address");
308	        }
309	        if (isBlank(ownerFieldsDto.getCity())) {
310	            invalidFields.add("city");
311	        }
312	        if (isBlank(ownerFieldsDto.getTelephone())) {
313	            invalidFields.add("telephone");
314	        }
315	        if (!invalidFields.isEmpty()) {
316	            throw new InvalidOwnerFieldsException(invalidFields);
317	        }
318	    }
319	
320	    private boolean isBlank(String value) {
321	        return value == null || value.isBlank();
322	    }
323	
324	    /**
325	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
326	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
327	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
328	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
329	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
330	     *
331	     * @param telephone the raw telephone value from the submitted owner payload
332	     * @return the normalized E.164 telephone number
333	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
334	     */
335	    private String normalizeTelephone(String telephone) {
336	        String raw = telephone == null ? "" : telephone.strip();
337	        boolean hasCountryCode = raw.startsWith("+");
338	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
339	        String digits;
340	        if (hasCountryCode) {
341	            digits = cleaned.substring(1);
342	        } else {
343	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
344	            digits = "61" + national;
345	        }
346	        if (!digits.matches("[0-9]{8,15}")) {
347	            throw new InvalidOwnerFieldsException(List.of("telephone"));
348	        }
349	        return "+" + digits;
350	    }
351	
352	    /**
353	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
354	     * returning {@code null} when the value cannot form a valid E.164 number.
355	     *
356	     * @param telephone an existing owner's stored telephone value
357	     * @return the E.164 form, or {@code null} if it cannot be normalized
358	     */
359	    private String toE164OrNull(String telephone) {
360	        try {
361	            return normalizeTelephone(telephone);
362	        } catch (InvalidOwnerFieldsException ex) {
363	            return null;
364	        }
365	    }
366	
367	    /**
368	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
369	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
370	     * accepted value is trimmed and lower-cased before it is stored and returned.
371	     *
372	     * @param email the raw email value from the submitted owner payload, may be {@code null}
373	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
374	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
375	     */
376	    private String normalizeEmail(String email) {
377	        if (email == null) {
378	            return null;
379	        }
380	        String trimmed = email.strip();
381	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
382	            throw new InvalidOwnerFieldsException(List.of("email"));
383	        }
384	        return trimmed.toLowerCase(Locale.ROOT);
385	    }
386	
387	    /**
388	     * Rejects creating an owner whose E.164 telephone is already used by any other owner.
389	     * Existing owners' telephones are converted to E.164 form before comparison so that
390	     * differently-formatted representations of the same number are treated as duplicates.
391	     *
392	     * @param normalizedTelephone the E.164 telephone of the owner being created
393	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same E.164 telephone
394	     */
395	    private void rejectDuplicateTelephone(String normalizedTelephone) {
396	        boolean duplicate = this.clinicService.findAllOwners().stream()
397	            .map(Owner::getTelephone)
398	            .filter(telephone -> telephone != null)
399	            .map(this::toE164OrNull)
400	            .filter(telephone -> telephone != null)
401	            .anyMatch(normalizedTelephone::equals);
402	        if (duplicate) {
403	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
404	        }
405	    }
406	
407	    /**
408	     * Rejects creating an owner whose last name and address both match an existing owner. Both fields
409	     * are compared case-insensitively with surrounding and repeated internal whitespace collapsed, so
410	     * that e.g. {@code "  110  W. Liberty  St. "} and {@code "110 w. liberty st."} are treated as the
411	     * same address. This guard is bypassed for a request that sets {@code sharesHousehold} true.
412	     *
413	     * @param lastName the last name of the owner being created
414	     * @param address the address of the owner being created
415	     * @throws DuplicateOwnerHouseholdException if another owner shares the same last name and address
416	     */
417	    private void rejectDuplicateHousehold(String lastName, String address) {
418	        String normalizedLastName = normalizeForComparison(lastName);
419	        String normalizedAddress = normalizeAddress(address);
420	        boolean duplicate = this.clinicService.findAllOwners().stream()
421	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
422	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())));
423	        if (duplicate) {
424	            throw new DuplicateOwnerHouseholdException(lastName, address);
425	        }
426	    }
427	
428	    /**
429	     * Assigns the owner being created a household identifier when the request opts into sharing a
430	     * household. The identifier is a stable value derived from the owner's normalized last name and
431	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
432	     * value regardless of creation order. Any already-existing owner in the same household that has no
433	     * identifier yet is back-filled with the same value so the whole household stays consistent.
434	     *
435	     * @param owner the owner being created, whose household id is set in place
436	     */
437	    private void assignHousehold(Owner owner) {
438	        String householdId = householdId(owner.getLastName(), owner.getAddress());
439	        String normalizedLastName = normalizeForComparison(owner.getLastName());
440	        String normalizedAddress = normalizeAddress(owner.getAddress());
441	        for (Owner existing : this.clinicService.findAllOwners()) {
442	            if (existing.getHouseholdId() == null
443	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
444	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
445	                existing.setHouseholdId(householdId);
446	                this.clinicService.saveOwner(existing);
447	            }
448	        }
449	        owner.setHouseholdId(householdId);
450	    }
451	
452	    /**
453	     * Derives the stable household identifier for a given last name and address. The value is
454	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
455	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
456	     * the same household therefore always produce the same identifier.
457	     *
458	     * @param lastName the owner's last name
459	     * @param address the owner's address
460	     * @return the stable household identifier
461	     */
462	    private String householdId(String lastName, String address) {
463	        String key = normalizeForComparison(lastName) + "\n" + normalizeAddress(address);
464	        try {
465	            byte[] digest = MessageDigest.getInstance("SHA-256")
466	                .digest(key.getBytes(StandardCharsets.UTF_8));
467	            StringBuilder hex = new StringBuilder();
468	            for (int i = 0; i < 6; i++) {
469	                hex.append(String.format("%02X", digest[i]));
470	            }
471	            return "HH-" + hex;
472	        } catch (NoSuchAlgorithmException ex) {
473	            throw new IllegalStateException("SHA-256 not available", ex);
474	        }
475	    }
476	
477	    /**
478	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
479	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
480	     * result is lower-cased. A {@code null} value normalizes to the empty string.
481	     *
482	     * @param value the value to normalize, may be {@code null}
483	     * @return the normalized value
484	     */
485	    private String normalizeForComparison(String value) {
486	        if (value == null) {
487	            return "";
488	        }
489	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
490	    }
491	
492	    /**
493	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
494	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
495	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
496	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
497	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
498	     * that is stored, returned, and used for every address comparison (household duplicate detection
499	     * and the shared household id).
500	     *
501	     * @param address the raw address value from the submitted owner payload, may be {@code null}
502	     * @return the normalized address
503	     */
504	    private String normalizeAddress(String address) {
505	        if (address == null) {
506	            return "";
507	        }
508	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
509	        if (collapsed.isEmpty()) {
510	            return "";
511	        }
512	        String[] tokens = collapsed.split(" ");
513	        StringBuilder normalized = new StringBuilder();
514	        for (int i = 0; i < tokens.length; i++) {
515	            if (i > 0) {
516	                normalized.append(' ');
517	            }
518	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
519	        }
520	        return normalized.toString();
521	    }
522	}
